1103	# warning on this rule produces a lot of noise.
1104	single_range_in_vec_init = "allow"
1105	
1106	# in Rust it can be very tedious to reduce argument count without
1107	# running afoul of the borrow checker.
1108	too_many_arguments = "allow"
1109	
1110	# We often have large enum variants yet we rarely actually bother with splitting them up.
1111	large_enum_variant = "allow"
1112	
1113	# Boolean expressions can be hard to read, requiring only the minimal form gets in the way
1114	nonminimal_bool = "allow"
