1128	# runs them without a `--path` argument. The `lints` package pins its own
1129	# nightly toolchain (see `tooling/lints/rust-toolchain.toml`) and is kept out of
1130	# this workspace on purpose.
1131	[workspace.metadata.dylint]
1132	libraries = [{ path = "tooling/lints" }]
